using System.IO;
using System.Diagnostics;
using System.Text;
namespace DanceStudio;
public static class AudioImport {
 public static WaveAudio Load(string path){using var file=File.OpenRead(path);using var reader=new BinaryReader(file);if(file.Length<12||file.Length>512L*1024*1024)throw new InvalidDataException(UiText.T("t0001"));string Tag()=>Encoding.ASCII.GetString(reader.ReadBytes(4));if(Tag()!="RIFF")throw new InvalidDataException(UiText.T("t0002"));uint declared=reader.ReadUInt32();string kind=Tag();if(kind=="WAVE")return WaveAudio.Load(path);if(kind!="XWMA")throw new InvalidDataException(UiText.T("t0003"));
  if(declared!=file.Length-8)throw new InvalidDataException(UiText.T("t0004"));
  int channels=0,rate=0;uint decodedBytes=0;bool data=false,format=false,index=false;while(file.Position+8<=file.Length){string tag=Tag();uint length=reader.ReadUInt32();long end=file.Position+length;if(end+(length&1)>file.Length)throw new InvalidDataException(UiText.T("t0005"));if(tag=="fmt "){if(format)throw new InvalidDataException(UiText.T("t0006"));format=true;if(length<16)throw new InvalidDataException(UiText.T("t0007"));int codec=reader.ReadUInt16();channels=reader.ReadUInt16();rate=reader.ReadInt32();if(codec!=0x161&&codec!=0x162)throw new NotSupportedException(UiText.T("t0008"));}if(tag=="data"){if(data)throw new InvalidDataException(UiText.T("t0009"));data=length>0;}if(tag=="dpds"){if(index)throw new InvalidDataException(UiText.T("t0010"));index=true;if(length<4||length%4!=0)throw new InvalidDataException(UiText.T("t0011"));uint previous=0;for(long i=0;i<length/4;i++){uint current=reader.ReadUInt32();if(current<previous)throw new InvalidDataException(UiText.T("t0012"));previous=current;}decodedBytes=previous;}file.Position=end+(length&1);}
  if(file.Position!=file.Length)throw new InvalidDataException(UiText.T("t0013"));
  if(!data||channels is <1 or >2||rate is <8000 or >192000||decodedBytes==0||decodedBytes>512L*1024*1024||decodedBytes%(channels*2)!=0)throw new InvalidDataException(UiText.T("t0014"));
  string? tool=Environment.GetEnvironmentVariable("DANCESTUDIO_FFMPEG");if(string.IsNullOrWhiteSpace(tool))tool=Path.Combine(AppContext.BaseDirectory,"Tools","ffmpeg.exe");if(!File.Exists(tool)){tool=(Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator).Select(x=>Path.Combine(x.Trim('"'),"ffmpeg.exe")).FirstOrDefault(File.Exists);}if(tool==null||!File.Exists(tool))throw new FileNotFoundException(UiText.T("t0015"));
  string temp=Path.Combine(Path.GetTempPath(),"DanceStudio-"+Guid.NewGuid().ToString("N")+".wav");try{var start=new ProcessStartInfo(tool){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};foreach(string arg in new[]{"-nostdin","-v","error","-f","xwma","-i",Path.GetFullPath(path),"-map","0:a:0","-vn","-acodec","pcm_s16le","-ar",rate.ToString(),"-ac",channels.ToString(),"-f","wav",temp})start.ArgumentList.Add(arg);using var process=Process.Start(start)??throw new IOException(UiText.T("t0016"));var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(120000)){process.Kill(true);throw new IOException(UiText.T("t0017"));}string message=errors.GetAwaiter().GetResult();if(process.ExitCode!=0)throw new IOException(UiText.T("t0018")+message[..Math.Min(1500,message.Length)]);var wave=WaveAudio.Load(temp);if(wave.Pcm.Length<decodedBytes)throw new InvalidDataException(UiText.T("t0019"));if(wave.Pcm.Length>decodedBytes)wave.Pcm=wave.Pcm[..checked((int)decodedBytes)];wave.RebuildPeaks();wave.Path=Path.GetFullPath(path);return wave;}finally{if(File.Exists(temp))File.Delete(temp);}
 }
}
